static const char* kGoldenAddDefault = R"GOLD(<fieldset><legend>Add camera</legend><form method="POST" action="/cameras/save"><label>Name (unique)<input type="text" name="name" value="" required></label><label>Device service URL, e.g. http://192.168.1.50/onvif/device_service<input type="text" name="deviceServiceUrl" value="" required></label><label>Username<input type="text" name="user" value=""></label><label>Password<input type="password" name="pass"></label><label class="checkbox"><input type="checkbox" name="enabled" checked> Enabled</label><label class="checkbox"><input type="checkbox" name="useWSSecurity" checked> Use WS-Security (uncheck for HTTP Basic Auth)</label><label class="checkbox"><input type="checkbox" name="includeInitialTerminationTime"> Include InitialTerminationTime</label><label class="checkbox"><input type="checkbox" name="includeReplyToAnonymous"> Include ReplyTo anonymous</label><label>Snapshot URI override (optional; {USER}/{PASS}/{WIDTH}/{HEIGHT} substituted at runtime)<input type="text" name="snapshotUriOverride" value=""></label><label>Snapshot width override, for {WIDTH} above (optional, max 4096, blank/0 = unset)<input type="text" name="snapshotMaxWidth" value=""></label><label>Snapshot height override, for {HEIGHT} above (optional, max 4096, blank/0 = unset)<input type="text" name="snapshotMaxHeight" value=""></label><label>Preferred profile keyword (optional, e.g. "sub")<input type="text" name="preferredProfileKeyword" value=""></label><label>Alert cooldown, seconds, max 86400 (minimum time between Telegram alerts for this camera)<input type="text" name="alertCooldownSec" value="30"></label><label>Offline threshold, minutes, max 10080 (no response for this long -> OFFLINE alert)<input type="text" name="offlineThresholdMin" value="5"></label><label>Snapshots per alert (1-10) - how many consecutive photos to send when motion fires, each a fresh fetch from the camera; raise it to see more of what led up to the alert<input type="text" name="snapshotBurstCount" value="1"></label><label>Poll interval, ms, 250-30000 (how often this camera is asked "anything new?" - lower notices motion sooner, at the cost of more frequent requests to this camera; some cheaper cameras' embedded HTTP stacks tolerate that worse than others)<input type="text" name="pollIntervalMs" value="2000"></label><label class="checkbox"><input type="checkbox" name="quietHoursEnabled"> Quiet hours (mutes motion alerts only - tamper/offline still alert)</label><label>Quiet hours start<input type="time" name="quietStart" value="00:00"></label><label>Quiet hours end<input type="time" name="quietEnd" value="00:00"></label><p class="hint">Leaving start and end the same (e.g. both 00:00) means no active window - quiet hours needs a real start/end to do anything.</p><label>No-motion watchdog, hours (0 = off) - alerts if this camera hasn't seen ANY motion in over this long, e.g. a dead PIR or a knocked-over camera<input type="text" name="motionWatchdogHours" value="0"></label><label>Timelapse capture, minutes (0 = off) - stores a snapshot on this interval regardless of motion, kept in history/SD<input type="text" name="timelapseIntervalMin" value="0"></label><label class="checkbox"><input type="checkbox" name="timelapseSendToTelegram"> Also send these scheduled snapshots to Telegram (in addition to storing them) - ignored while the interval above is 0</label><label>Snapshot retention override, days (0 = use the Storage page's global setting)<input type="text" name="retentionDays" value="0"></label><label class="checkbox"><input type="checkbox" name="personAlertsEnabled" checked> Alert on person detection - on by default; only uncheck to mute person alerts for this specific camera while leaving other detection types alone (requires a camera whose own ONVIF AI actually distinguishes person detection - a plain motion sensor always alerts regardless of this)</label><label class="checkbox"><input type="checkbox" name="vehicleAlertsEnabled" checked> Alert on vehicle detection - on by default; uncheck for a camera facing a busy street that would otherwise page you for every passing car</label><label class="checkbox"><input type="checkbox" name="petAlertsEnabled"> Alert on pet (dog/cat) detection too - off by default, since a person/vehicle-only camera would otherwise page you for your own pet</label><label class="checkbox"><input type="checkbox" name="petAlertsTextOnly"> Send pet alerts as text only, no photo - ignored unless pet alerts above are on</label><label class="checkbox"><input type="checkbox" name="motionDigestEnabled" checked> Send a follow-up "motion continued" summary after a real alert's cooldown ends - on by default; uncheck for a camera busy enough that the follow-up summary is itself noise on top of the alert it's summarizing</label><label>Notes<input type="text" name="notes" value=""></label><p><button type="submit" formaction="/cameras/save">Add camera</button> <button type="submit" formaction="/cameras/test">Test Connection</button></p></form></fieldset>)GOLD";

